 "new_string": "def transform(grid):
    """Recolor edge-connected 4-cell runs to 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # In the demo, edge contact is through a 9 boundary: cells 4s in border-adjacent
    # bracketed lines are the marked segments; all other 4s remain unchanged.
    # Mark the connected 4-component(s) that touch the outer border, including
    # diagonal contact so line endpoints at grid edges are included.
    stack = []
    for c in range(w):
        if grid[0][c] == 4: stack.append((0,c))
        if grid[h-1][c] == 4: stack.append((h-1,c))
    for r in range(h):
        if grid[r][0] == 4: stack.append((r,0))
        if grid[r][w-1] == 4: stack.append((r,w-1))
    seen = set(stack)
    while stack:
        r,c = stack.pop()
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                nr,nc = r+dr,c+dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 4 and (nr,nc) not in seen:
                    seen.add((nr,nc)); stack.append((nr,nc))
    for r,c in seen:
        out[r][c] = 2
    # The task has interior runs continuing the same straight border-reaching strips.
    # Recolor any complete straight run of 4s bracketed by 9s whose orientation
    # is present among border-touching marked runs.
    marked_rows = {r for r,c in seen if c == 0 or c == w-1}
    marked_cols = {c for r,c in seen if r == 0 or r == h-1}
    for r in marked_rows:
        for c in range(w):
            if grid[r][c] == 4: out[r][c] = 2
    for c in marked_cols:
        for r in range(h):
            if grid[r][c] == 4: out[r][c] = 2
    return out
