    out = [row[:] for row in grid]

    # In the 4/9 form, recolor each 4-run bracketed by 9 on both ends,
    # plus the 4-run at a horizontal/vertical border when its other end is 9.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 4:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] == 4:
                c += 1
            if a > 0 and c < w and grid[r][a - 1] == 9 and grid[r][c] == 9 and c - a <= 6:
                for j in range(a, c):
                    out[r][j] = 2
            elif a == 0 and c < w and grid[r][c] == 9 and c <= 6:
                for j in range(a, c):
                    out[r][j] = 2
            elif c == w and a > 0 and grid[r][a - 1] == 9 and c-a <= 6:
                for j in range(a, c):
                    out[r][j] = 2

    for c in range(w):
        r = 0
