 "content": "def transform(grid):
    """Connect collinear markers within dense marker rows/columns."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    marker = min(freq, key=freq.get)
    bg = max(freq, key=freq.get)
    out = [row[:] for row in grid]
    # A line with a clear cluster of at least four markers is a stroke; bridge gaps.
    for r in range(h):
        pos = [c for c in range(w) if grid[r][c] == marker]
        if len(pos) >= 4:
            for a, b in zip(pos, pos[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        pos = [r for r in range(h) if grid[r][c] == marker]
        if len(pos) >= 4:
            for a, b in zip(pos, pos[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out

if __name__ == '__main__':
    # Test grid
    test = [[9,9,9,9,4,9,4,4,4,9,4,4,4,9,4,4,9,9,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9]*19,[9,9,9,9,4,9,4,4,4,4,9,9,4,4,4,4,4,4,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,9],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9,9,9,9,4,4,9,4,9,4,4,9,9,4,9,4,9,4,4],[9]*19,[9]*19,[9]*19]
    print(transform(test))
    # Demo 4 exact pattern smoke test for prominent horizontal/vertical strokes.
    d = [[8]*18 for _ in range(16)]
    for r,c in [(4,3),(4,4),(4,5),(4,6),(4,8),(4,11),(4,12),(4,15),(4,16),(5,3),(5,10),(6,3),(6,10),(7,3),(7,16),(8,3),(8,10),(8,16),(9,10),(9,16),(10,10),(10,16),(11,4),(11,5),(11,6),(11,8),(11,9),(11,10),(11,11),(11,13),(11,14),(11,16)]: d[r][c]=4
